-- Seed de pruebas: 40 trabajos para tienda 99 con un PDF en blanco.
-- Ejecutar en DBeaver contra la BD remota de SAP/Postgres.
--
-- Nota:
-- - Insertamos en `sap.print_queue_aux`.
-- - Si tu tabla está en otro schema, cambia `sap.` por el schema real.
-- - Usamos `ON CONFLICT (external_id) DO NOTHING` para no duplicar.

WITH pdf AS (
    SELECT decode(
        '',
        'hex'
    ) AS pdf_blob
),
nums AS (
    SELECT generate_series(1, 40) AS n
)
INSERT INTO sap.print_queue_aux
    (external_id, document_type, store_code, processed, claimed_by, lease_expires_at_utc, pdf_blob, created_at_utc)
SELECT
    -- Sufijo timestamp para que cada ejecución genere external_id nuevos.
    -- Evita:
    -- - ON CONFLICT (external_id) DO NOTHING en el INSERT
    -- - el descarte idempotente local (PrintJobs) cuando external_id ya existe.
    format(
        'TEST-ALB-99-%02s-%s',
        nums.n,
        to_char(clock_timestamp(), 'YYYYMMDDHH24MISSFF3')
    ) AS external_id,
    'ALBARAN' AS document_type,
    '99' AS store_code,
    FALSE AS processed,
    NULL AS claimed_by,
    NULL AS lease_expires_at_utc,
    pdf.pdf_blob,
    NOW() AS created_at_utc
FROM nums
CROSS JOIN pdf
ON CONFLICT (external_id) DO NOTHING;

